// Chunk 51, gap-g1#1 (the trace verifier's test). The wallet's own Seedelf A
// sits in the contract under its register D, an inline datum anyone can read.
// Mallory, a stranger, pays the contract 40 ₳ under D byte for byte (d = 1):
// she needs nothing secret, only A's UTxO. The wallet's ownership check is
// g^x == u alone (balances.ts ownedUtxos, register.rs is_owned), so it counts
// her UTxO as its own, and the Seedelf history notes it as a payment received
// (activity.ts arrived and classOf: received:<tx>), as it notes Bob's 60 ₳,
// paid properly under a fresh re-randomization. Nothing compares her register
// with A's, though the kept view holds both.
//
// A stealth mint ranks Received first (core build.rs Purpose::Mint) and a
// session's funding does too (Purpose::Fund), each taking the smallest UTxO
// that pays alone. So both take Mallory's 40 ₳ ahead of Bob's 60 ₳. On chain
// each then spends an input whose datum is A's: anyone can see its spender
// holds A's key, so the new Seedelf (named after that input, too) and the
// swap's one-time account are tied to A, and through A's own mint to the
// public account that paid for it. The mint form says "Only money others paid
// you keeps the Seedelf apart from your public account", and the review has
// no note (one class).
//
// What's right (the finding's fix (a); the owner decides how): a UTxO under a
// register the chain already ties to one of the wallet's own Seedelfs is never
// what these spends take ahead of a payment made properly that pays alone.
// Driven through the worker's services with the real WebAssembly, as
// mint.test.ts and history-classes.test.ts are.

import { describe, expect, it } from "vitest";

import { CONTRACT_V1 } from "../src/background/balances";
import { txInputs } from "../src/background/cbor";
import type { KoiosUtxo } from "../src/background/koios";
import { SESSION_MINT } from "../src/background/mint";
import { SESSION_OUT } from "../src/background/sessions";
import { historiesNote } from "../src/shared/histories";
import { loadTestWasm, minswapEstimate, ownedUtxos, testBalances, vectors, withdrawPreprod } from "./fakes";

const PASSWORD = "correct horse battery";
const inputsOf = (cbor: string) => txInputs(Uint8Array.from(Buffer.from(cbor, "hex")));

describe("r51 gap-g1#1: a stranger's payment under one of the wallet's Seedelfs' datum, as found", () => {
  it("is never what a stealth mint or a swap's funding takes first while a payment made properly pays alone", { timeout: 60_000 }, async () => {
    const v = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
    const t = testBalances();
    await t.wallet.create(v.phrase, PASSWORD);
    // One spend: a funding that takes one UTxO alone (history-classes.test.ts, L41).
    const evaluation = withdrawPreprod.amount.evaluation as { result: unknown[] };
    t.koios.evaluation = { ...evaluation, result: evaluation.result.slice(0, 1) };
    // The history's first reading: the 25 ₳ and the 3 ₳ with tokens are already there (Unknown); a3 is Seedelf A.
    await t.balances.get("preprod");

    const seedelfA = ownedUtxos.find((u) => (u.asset_list ?? []).some((a) => a.policy_id === CONTRACT_V1.seedelfPolicyId))!;
    const wasm = loadTestWasm();
    const fresh = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
    const paid = (txHash: string, lovelace: string, inline_datum: KoiosUtxo["inline_datum"]): KoiosUtxo => ({
      ...ownedUtxos[0]!,
      tx_hash: txHash,
      tx_index: 0,
      value: lovelace,
      asset_list: [],
      inline_datum,
      block_height: 9_000_001,
    });
    // Bob pays A as any wallet does, under a fresh re-randomization; Mallory under A's datum as found.
    const bob = paid("b0".repeat(32), "60000000", { bytes: fresh, value: null });
    const mallory = paid("e7".repeat(32), "40000000", seedelfA.inline_datum);
    const M = `${mallory.tx_hash}#0`;
    const B = `${bob.tx_hash}#0`;
    t.koios.added.push(bob, mallory);
    t.clock.now += 60_000;
    await t.balances.get("preprod", true);

    // What holds today, and still would once fixed: anyone can read that her datum is A's, and both are the wallet's.
    expect(mallory.inline_datum!.bytes).toBe(seedelfA.inline_datum!.bytes);
    expect((seedelfA.asset_list ?? []).map((a) => a.asset_name)[0]).toMatch(/^5eed0e1f/);
    const classes = await t.activity.classes("preprod", [bob, mallory]);
    console.log("[r51 gap-g1#1] classes:", JSON.stringify(Object.fromEntries(classes)));
    expect(classes.get(B)).toEqual({ id: `received:${bob.tx_hash}`, origin: "received" });

    // 1. A stealth mint from the private balance.
    const minted = await t.mint.build("preprod", "", "seedelf");
    const mintInputs = inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor);
    console.log(
      "[r51 gap-g1#1] stealth mint spends",
      JSON.stringify(mintInputs.map((i) => (i === M ? "Mallory's 40 ₳ under A's datum" : i === B ? "Bob's 60 ₳" : i))),
      "named",
      minted.tokenName,
      "histories",
      JSON.stringify(minted.histories),
      "note",
      JSON.stringify(historiesNote(minted.histories) ?? null),
    );

    // 2. A private swap's funding, paying a new one-time account.
    const quote = await t.sessions.quote("preprod", minswapEstimate.ask);
    const out = await t.sessions.outBuild("preprod", quote);
    const outInputs = inputsOf((await t.session.get<{ txCbor: string }>(SESSION_OUT))!.txCbor);
    console.log(
      "[r51 gap-g1#1] swap funding pays",
      out.payments.map((p) => p.lovelace).join(" + "),
      "and spends",
      JSON.stringify(outInputs.map((i) => (i === M ? "Mallory's 40 ₳ under A's datum" : i === B ? "Bob's 60 ₳" : i))),
    );

    // Neither takes Mallory's copy of A's datum ahead of Bob's payment, which pays each alone.
    expect.soft(mintInputs, "the stealth mint's inputs").not.toContain(M);
    expect.soft(outInputs, "the swap funding's inputs").not.toContain(M);
  });
});

// Chunk 51, finding gap-g4#1: a split route's second leg, paid in a block that lands between the runner's listing of
// the account (sessions.ts act, `rows`) and its lookup of the orders (liveOrders, utxo_info). Every order then reads
// spent, and the runner reads the account again for the outcome (`since`, independent review M18), a reading that
// holds the leg. The return is built from the first reading all the same (`bringBack(..., rows)`), so the leg is left
// out of it. Through Lovejoin, that chain puts the session's 5 ₳ collateral into the 5 ₳ pool, and the leg then comes
// back alone in a second return, directly: "its 5 ₳ collateral isn't at its account anymore, and the mixes need it".
// Right: the session's first return takes every leg the runner found, and nothing comes back after it without Lovejoin.
// Real WebAssembly and Lovejoin v2's 5 ₳ pool, as tests/lovejoin-planner.test.ts sets them up.
import { describe, expect, it } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import { LovejoinService, type PoolRef } from "../src/background/lovejoin";
import { Minswap } from "../src/background/minswap";
import { SESSION_CHAIN_PREFIX, SessionService } from "../src/background/sessions";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, testBalances, vectors } from "./fakes";
import { ASK, atSession, MIN, orderRow, SWAP_TX } from "./swap-session";
import { ADA_POOL, ADA_ROWS } from "./v2-pools";

const PASSWORD = "correct horse battery";
const PHRASE = (vectors("cardano_account.json") as Array<{ account: number; phrase: string }>).find(
  (v) => v.account === 0 && v.phrase.split(" ").length === 12,
)!.phrase;
/** Ogmios's answer when the network measures no more than a transaction declares. */
const AGREES = { jsonrpc: "2.0", method: "evaluateTransaction", result: [] };

type T = ReturnType<typeof testBalances>;
type Step = { kind: string; txCbor: string; txHash: string };
type Sealed = { closedAt?: number; lovejoinSkipped?: string; txs: Array<{ kind: string; txHash: string; replaced?: boolean }> };

/** Lovejoin reading `pools`, giveme.my's witness stood in for (lovejoin-planner.test.ts `pooled`). */
function pooled(t: T, pools: PoolRef[]): LovejoinService {
  const wasm = loadTestWasm();
  return new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => pools,
    random: () => 0.5,
  });
}

/** The sessions over `lj`, the one-time key's script signature stood in for (lovejoin-planner.test.ts `runner`). */
function runner(t: T, lj: LovejoinService): SessionService {
  const wasm = loadTestWasm();
  return new SessionService({
    ...t.deps,
    wasm: {
      ...wasm,
      signScriptSpend: (_key: unknown, request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
    lovejoin: lj,
    sleep: async () => undefined,
  });
}

describe("a split route's leg paid between the runner's two readings of the account (chunk 51, gap-g4#1)", { timeout: 600_000 }, () => {
  it("comes back in the session's first return, through Lovejoin as approved, never alone after it", async () => {
    const t = testBalances();
    await t.wallet.create(PHRASE, PASSWORD);
    t.koios.evaluation = AGREES;
    // A slot in preprod's Shelley era, for what the account signs (lovejoin-flows.test.ts).
    t.koios.tip = 110_000_000;
    t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
    await t.deps.preferences.set({ lovejoinDepth: 1 });
    const sessions = runner(t, pooled(t, [ADA_POOL]));

    // Session 0 sold MIN for ADA through Lovejoin, as approved, one wave deep; Minswap split it into two orders,
    // SWAP_TX#0 and #2, both landed. Its funding (FUND) paid it the 5 ₳ collateral too.
    const now = t.clock.now;
    const FUND = "01".repeat(32);
    const orders = [`${SWAP_TX}#0`, `${SWAP_TX}#2`];
    await t.store.set("sessions.preprod", {
      next: 1,
      sessions: [
        {
          index: 0,
          ownStake: true,
          createdAt: now,
          txs: [
            { kind: "out", txHash: FUND, at: now, confirmed: true },
            { kind: "swap", txHash: SWAP_TX, at: now, confirmed: true, orders, minAmountOut: "40000000" },
          ],
          swap: { ...ASK, tokenIn: MIN, tokenOut: "lovelace", amount: "906594100", amountOut: "41000000", minAmountOut: "40000000" },
          auto: {
            approved: { minAmountOut: "40000000", fund: { lovelace: "16000000", tokens: [] } },
            direct: false,
            lovejoin: { depth: 1, delay: "1-6", box: "5000000" },
          },
        },
      ],
    });
    // The account: the swap's change, the collateral, and leg 1's fill (20 ₳), listed; both orders spent at the DEX's
    // contract; the 5 ₳ pool's 20 boxes of other people's.
    t.koios.addedToAccounts.push(
      atSession(SWAP_TX, 1, "2000000"),
      atSession(FUND, 1, "5000000"),
      ...orders.map((o) => orderRow(SWAP_TX, Number(o.split("#")[1]))),
      atSession("aa".repeat(32), 0, "20000000"),
      ...ADA_ROWS,
    );
    for (const o of orders) t.koios.spent.add(o);
    // Leg 2's fill (20 ₳) lands in the block between the runner's listing and its lookup of the orders.
    const LATE = `${"bb".repeat(32)}#0`;
    const late = [atSession("bb".repeat(32), 0, "20000000")];
    const real = t.koios.fetch;
    t.koios.fetch = async (url, init) => {
      const path = new URL(url).pathname.split("/").pop();
      const refs = typeof init?.body === "string" ? (JSON.parse(init.body) as { _utxo_refs?: string[] })._utxo_refs : undefined;
      if (path === "utxo_info" && refs?.includes(orders[0]!)) t.koios.addedToAccounts.push(...late.splice(0));
      return real(url, init);
    };
    const book = async () => (await t.store.get<{ sessions: Sealed[] }>("sessions.preprod"))!.sessions[0]!;
    const before = t.koios.submitted.length;

    // The runner's runs until it sends the session's first return: a chain through Lovejoin, kept as it's sent, or one
    // that comes back directly. A fix may wait a run for the leg to be listed, so up to three.
    let first: Uint8Array[] = [];
    for (let run = 0; run < 3 && !first.length; run++) {
      await sessions.advance("preprod", 0, true);
      const chain = await t.wallet.withKeys(() => t.session.get<{ txs: Step[] }>(`${SESSION_CHAIN_PREFIX}preprod.0`));
      if (chain) first = chain.txs.map((x) => Uint8Array.from(Buffer.from(x.txCbor, "hex")));
      else if ((await book()).txs.some((x) => x.kind === "back")) first = t.koios.submitted.slice(before);
    }
    expect(first.length).toBeGreaterThan(0);

    // It lands, and the runner runs on until the session closes: whatever is left at the account comes back.
    t.koios.confirmations = 1;
    for (let run = 0; run < 10 && !(await book()).closedAt; run++) {
      for (const tx of t.koios.submitted) for (const o of txInputs(tx)) t.koios.spent.add(o);
      await sessions.advance("preprod", 0, true);
    }
    const s = await book();
    expect({
      closed: s.closedAt !== undefined,
      // The first return takes leg 2's fill.
      firstTakesLate: first.some((tx) => txInputs(tx).includes(LATE)),
      // One return: the chain's, nothing after it.
      returns: s.txs.filter((x) => x.kind === "back" && !x.replaced).length,
      // Nothing came back saying Lovejoin was left out.
      lovejoinSkipped: s.lovejoinSkipped,
    }).toEqual({ closed: true, firstTakesLate: true, returns: 1, lovejoinSkipped: undefined });
  });
});

// Chunk 51, finding gap-g4#2 (the trace verifier's test). A swap's funding pays its one-time account two outputs: the
// swap with its costs (and the collateral's mix's reserve), and exactly 5 ₳, the account's own collateral (outBuild).
// Minswap's build-tx takes only the sender and picks the sender's UTxOs itself (minswap.ts). Nothing the runner checks
// before it signs (inspect, refuseOddities, checkOrder, cancelsChecked, withinFunding) looks at which of the session's
// UTxOs the swap spends, so a swap that spends the 5 ₳ too is signed and sent. The 5 ₳ joins the swap's change, and
// after the fill no exact 5 ₳ is left (collateralFits): the return, approved through Lovejoin, comes back directly,
// "its 5 ₳ collateral isn't at its account anymore, and the mixes need it" (NO_COLLATERAL), its collateral unmixed.
// Right: the approval's way back holds. Either the runner signs no swap that spends the session's 5 ₳ collateral, or
// the return after such a swap still goes through Lovejoin, nothing left out for want of that collateral.
// The harness is r51-gap-g4-1.test.ts's: the real WebAssembly, v2's 5 ₳ pool, and fakes of Koios, giveme.my and
// Minswap's aggregator, whose build-tx answers the swap given. Its control, the same swap spending the swap's output
// alone, is signed and comes back through Lovejoin: only the inputs Minswap picked differ.
import { describe, expect, it } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import { LovejoinService, type PoolRef } from "../src/background/lovejoin";
import { Minswap } from "../src/background/minswap";
import { SessionService } from "../src/background/sessions";
import { t as tr } from "../src/i18n";
import { txIdOf } from "./fixtures/cbor";
import { bytes, cbor, type Cbor, hex, ORDER_ADDRESS, ORDER_DATUM, ORDER_DATUM_HASH, SESSION_ADDRESS } from "./fixtures/swap-tx";
import { loadTestWasm, testBalances, vectors } from "./fakes";
import { atSession, MIN, orderRow } from "./swap-session";
import { ADA_POOL, ADA_ROWS } from "./v2-pools";

const PASSWORD = "correct horse battery";
const PHRASE = (vectors("cardano_account.json") as Array<{ account: number; phrase: string }>).find(
  (v) => v.account === 0 && v.phrase.split(" ").length === 12,
)!.phrase;
/** Ogmios's answer when the network measures no more than a transaction declares. */
const AGREES = { jsonrpc: "2.0", method: "evaluateTransaction", result: [] };

/** The session's funding: output 0 the swap and its costs, output 1 the account's own 5 ₳ collateral. */
const FUND = "01".repeat(32);
const SWAP_IN = `${FUND}#0`;
const COLLATERAL = `${FUND}#1`;
/** The MIN it sells. */
const SOLD = 906_594_100n;
/** Its costs as quoteOf funds them (the DEX's 2 ₳ fee, the 2 ₳ deposit, no Minswap fee on preprod, the 2 ₳ room), and the collateral's mix's 1.5 ₳ reserve. */
const FUNDED = 7_500_000n;
/** What the order holds beside the MIN (the batcher's fee and the deposit), and the swap's fee. */
const ORDERED = 4_000_000n;
const FEE = 205_189n;
/** The fill: the ADA bought and the deposit back. */
const FILL_TX = "aa".repeat(32);
const FILLED = "908594100";

const minValue = (lovelace: bigint, quantity: bigint): Cbor => ({
  raw: hex([0x82, ...cbor(lovelace), 0xa1, 0x58, 0x1c, ...bytes(MIN.slice(0, 56)), 0xa1, 0x43, ...bytes(MIN.slice(56)), ...cbor(quantity)]),
});

/**
 * Minswap's swap of the MIN for ADA from session 0's account, shaped as fixtures/swap-tx.ts has Minswap's V1 order (the
 * order at its script, its datum by hash in the witness set, the change back): spending the swap's output alone, or
 * (`collateralToo`) both of the funding's outputs, as a coin selection that takes every UTxO the sender holds would.
 */
function swapOf(collateralToo: boolean): { cbor: string; change: bigint } {
  const change = FUNDED + (collateralToo ? 5_000_000n : 0n) - ORDERED - FEE;
  const body = new Map<number, Cbor>([
    [0, { tag: 258, of: collateralToo ? [[bytes(FUND), 0], [bytes(FUND), 1]] : [[bytes(FUND), 0]] }],
    [
      1,
      [
        new Map<number, Cbor>([
          [0, bytes(ORDER_ADDRESS)],
          [1, minValue(ORDERED, SOLD)],
          [2, [0, bytes(ORDER_DATUM_HASH)]],
        ]),
        new Map<number, Cbor>([
          [0, bytes(SESSION_ADDRESS)],
          [1, change],
        ]),
      ],
    ],
    [2, FEE],
    [3, 134_639_865],
  ]);
  const witnesses = new Map<number, Cbor>([[4, { tag: 258, of: [{ raw: ORDER_DATUM }] }]]);
  return { cbor: hex(cbor([body, witnesses, true, null])), change };
}

type T = ReturnType<typeof testBalances>;
type Record = {
  lovejoinSkipped?: string;
  chain?: unknown;
  auto?: { paused?: { why: string; detail?: string }; retry?: { error: string }; filled?: number };
  txs: Array<{ kind: string; txHash: string }>;
};

/** Lovejoin reading `pools`, giveme.my's witness stood in for (lovejoin-planner.test.ts `pooled`). */
function pooled(t: T, pools: PoolRef[]): LovejoinService {
  const wasm = loadTestWasm();
  return new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => pools,
    random: () => 0.5,
  });
}

/** The sessions over `lj`, the one-time key's script signature stood in for (lovejoin-planner.test.ts `runner`). */
function runner(t: T, lj: LovejoinService): SessionService {
  const wasm = loadTestWasm();
  return new SessionService({
    ...t.deps,
    wasm: {
      ...wasm,
      signScriptSpend: (_key: unknown, request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
    lovejoin: lj,
    sleep: async () => undefined,
  });
}

/**
 * Session 0 sells the MIN for ADA, approved through Lovejoin one wave deep, its collateral's mix paid for, as outSubmit
 * records it; its funding landed, and no order yet. The account holds both of the funding's outputs, and v2's 5 ₳ pool
 * its 20 boxes of other people's. The runner places the order from what Minswap builds (`collateralToo`, swapOf). If
 * it signs it, the swap lands, the batcher fills it, and the runner runs until the session's return goes.
 */
async function swapped(collateralToo: boolean) {
  const t = testBalances();
  await t.wallet.create(PHRASE, PASSWORD);
  t.koios.evaluation = AGREES;
  // A slot in preprod's Shelley era, for what the account signs (lovejoin-flows.test.ts).
  t.koios.tip = 110_000_000;
  t.koios.confirmations = 1;
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  await t.deps.preferences.set({ lovejoinDepth: 1 });
  const swap = swapOf(collateralToo);
  const SWAP_TX = txIdOf(bytes(swap.cbor));
  t.minswap.swapCbor = swap.cbor;
  const sessions = runner(t, pooled(t, [ADA_POOL]));
  const now = t.clock.now;
  await t.store.set("sessions.preprod", {
    next: 1,
    sessions: [
      {
        index: 0,
        ownStake: true,
        createdAt: now,
        txs: [{ kind: "out", txHash: FUND, at: now, confirmed: true, outs: [SWAP_IN, COLLATERAL] }],
        swap: { amount: SOLD.toString(), tokenIn: MIN, tokenOut: "lovelace", slippage: 0.5, amountOut: "906594100", minAmountOut: "902083681" },
        auto: {
          approved: {
            minAmountOut: "902083681",
            fund: { lovelace: "6000000", tokens: [{ policyId: MIN.slice(0, 56), assetName: MIN.slice(56), quantity: SOLD.toString() }] },
            aggregatorFee: "0",
          },
          direct: false,
          lovejoin: { depth: 1, delay: "1-6", box: "5000000" },
        },
        collateralReserve: true,
      },
    ],
  });
  t.koios.addedToAccounts.push(atSession(FUND, 0, FUNDED.toString(), [[MIN, SOLD.toString()]]), atSession(FUND, 1, "5000000"), ...ADA_ROWS);
  const book = async () => (await t.store.get<{ sessions: Record[] }>("sessions.preprod"))!.sessions[0]!;

  // The runner places the order: Minswap's swap, the checks, the session's key.
  await sessions.advance("preprod", 0, true);
  const sent = t.koios.submitted.map((tx) => ({ id: txIdOf(tx), inputs: txInputs(tx) }));
  const signed = sent.find((x) => x.id === SWAP_TX);
  if (!signed) return { signed: false, spentCollateral: sent.some((x) => x.inputs.includes(COLLATERAL)), s: await book() };

  // It lands: the order waits at Minswap V1's script, and its change is at the account.
  for (const o of signed.inputs) t.koios.spent.add(o);
  t.koios.addedToAccounts.push(atSession(SWAP_TX, 1, swap.change.toString()), {
    ...orderRow(SWAP_TX, 0, ORDERED.toString()),
    asset_list: atSession(SWAP_TX, 0, "0", [[MIN, SOLD.toString()]]).asset_list,
  });
  await sessions.advance("preprod", 0, true);

  // The batcher fills it: the order is spent, and the ADA bought arrives. The runner runs until a return goes, its
  // chain through Lovejoin or one that comes back directly.
  t.koios.spent.add(`${SWAP_TX}#0`);
  t.koios.addedToAccounts.push(atSession(FILL_TX, 0, FILLED));
  for (let run = 0; run < 4; run++) {
    const r = await book();
    if (r.chain !== undefined || r.txs.some((x) => x.kind === "back")) break;
    await sessions.advance("preprod", 0, true);
  }
  const s = await book();
  return { signed: true, spentCollateral: signed.inputs.includes(COLLATERAL), s };
}

/** What the session's return did: through Lovejoin (its chain recorded), or why Lovejoin was left out. */
const wayBack = (s: Record) => ({
  filled: s.auto?.filled !== undefined,
  returned: s.chain !== undefined || s.txs.some((x) => x.kind === "back"),
  throughLovejoin: s.chain !== undefined,
  lovejoinSkipped: s.lovejoinSkipped,
  paused: s.auto?.paused,
});
const AS_APPROVED = { filled: true, returned: true, throughLovejoin: true, lovejoinSkipped: undefined, paused: undefined };

describe("a swap Minswap builds spending the session's own 5 ₳ collateral (chunk 51, gap-g4#2)", { timeout: 900_000 }, () => {
  it("never costs the session the Lovejoin return its approval promised", async () => {
    // The control: Minswap's swap leaves the 5 ₳ alone. It's signed, and the return goes through Lovejoin.
    const control = await swapped(false);
    expect({ signed: control.signed, spentCollateral: control.spentCollateral, ...wayBack(control.s) }).toEqual({
      signed: true,
      spentCollateral: false,
      ...AS_APPROVED,
    });

    // Minswap's swap spends the 5 ₳ too. A runner that won't sign it is right; one that signs it must still bring the
    // session back through Lovejoin, as approved.
    const both = await swapped(true);
    if (!both.signed) {
      expect(both.spentCollateral).toBe(false);
      return;
    }
    expect({
      signed: both.signed,
      spentCollateral: both.spentCollateral,
      skippedForWantOfTheCollateral: both.s.lovejoinSkipped === tr("sess.skip.warn.noCollateral"),
      ...wayBack(both.s),
    }).toEqual({
      signed: true,
      spentCollateral: true,
      skippedForWantOfTheCollateral: false,
      ...AS_APPROVED,
    });
  });
});

