import { describe, expect, it } from "vitest";

import type { KoiosUtxo } from "../src/background/koios";
import * as LovejoinScreen from "../src/ui/screens/Lovejoin";
import { publicFunded, type Tested } from "./chain-fixtures";
import { deepRow, withRawRows } from "./fakes";
import { ADA, ADA_BOX } from "./v2-pools";

const { mixOffer, publicSideOf } = LovejoinScreen;

/** Real chains are built and measured in WebAssembly: seconds each, more on CI. */
const SLOW = { timeout: 300_000 };

/** A native script of one key, `[0, keyhash]`: 32 bytes of CBOR, which Koios gives, so it's measurable. */
const SCRIPT = { hash: "ab".repeat(28), size: 32, type: "timelock", bytes: `8200581c${"cd".repeat(28)}` };

/** What a stranger puts at the account's 0/0, beside e6…#0 (`at`, the row it's made like). */
type Stranger = (t: Tested, at: KoiosUtxo) => void;

/** 30 ₳ of ADA alone carrying SCRIPT. */
const withScript: Stranger = (t, at) => {
  t.koios.addedToAccounts.push({ ...at, tx_hash: "e8".repeat(32), value: "30000000", reference_script: SCRIPT } as KoiosUtxo);
};

/** 3 ₳ of ADA alone whose inline datum is a list nested 200 levels deep. */
const withDeepDatum: Stranger = (t, at) => {
  withRawRows(t.koios, at.payment_cred!, [deepRow(at, 200, { txHash: "e9".repeat(32) })]);
};

/**
 * The public account: e6…#0 holds `lovelace`, beside its 5 ₳ collateral and the stranger's UTxO, and the UTxOs of ADA
 * alone it was recorded with are kept out of payments, so e6 is the only UTxO of ADA alone the chain may spend.
 * Lovejoin one wave deep, three boxes a mix: a box costs 5 ₳ and a mix's 0.95 ₳, and the funding keeps 1.5 ₳ beside
 * them. What the page has of it: Home's figure, and the account's UTxOs as its `utxos` read gives them (coin-control's
 * lists).
 */
async function account(lovelace: string, stranger: Stranger) {
  const t = await publicFunded(lovelace);
  await t.deps.preferences.set({ lovejoinDepth: 1 });
  const at = t.koios.addedToAccounts.find((u) => u.tx_hash === "e6".repeat(32))!;
  stranger(t, at);
  const home = (await t.balances.get("preprod")).cardano;
  let { cardano: utxos } = await t.coins.lists("preprod");
  const ours = ["e6", "e8", "e9"].map((x) => x.repeat(32));
  for (const u of utxos.filter((u) => !u.tokens.length && !u.collateral && !u.locked && !ours.includes(u.txHash))) {
    ({ cardano: utxos } = await t.coins.setLocked("preprod", "cardano", `${u.txHash}#${u.index}`, true));
  }
  return { t, home, utxos };
}

/** Review of `boxes` boxes from that account: what it built, or why not. */
async function review(t: Tested, boxes: number): Promise<string> {
  return t.lovejoin.publicBuild("preprod", boxes, { pool: ADA }).then(
    (s) => `built ${s.boxes}`,
    (e: unknown) => (e as Error).message,
  );
}

/**
 * The Mix form at one box, as the page has it (Lovejoin.tsx): its figure (publicSideOf), the stepper's most (mixOffer,
 * the pool's room left at ten), and Review at that most, on a fresh copy of the account.
 */
async function mixForm(lovelace: string, stranger: Stranger) {
  const { t, home, utxos } = await account(lovelace, stranger);
  const funding = await t.lovejoin.funding("preprod", 1, false, undefined, ADA);
  const { side, mixable } = publicSideOf(home, utxos, undefined, 1);
  const { most } = mixOffer("public", side, undefined, funding, ADA_BOX, 10, 1, 0n, mixable ? utxos : undefined);
  return { depth: funding.depth, mixable, spendable: side?.lovelace, most, review: await review(t, most) };
}

describe("gap-g2#3: the public Mix form counts only what the chain's pick can spend", SLOW, () => {
  it("leaves out a stranger's UTxO holding a reference script Koios gives the bytes of", async () => {
    // What the chain pays for: three boxes from e6's 20 ₳ (19.35 ₳), and not four (25.3 ₳); the stranger's 30 ₳ never.
    expect(await review((await account("20000000", withScript)).t, 3)).toBe("built 3");
    expect(await review((await account("20000000", withScript)).t, 4)).toMatch("doesn't pay for 4 boxes");
    // The form: its figure is what the chain can spend, and its stepper offers what the chain pays for.
    expect(await mixForm("20000000", withScript)).toEqual({ depth: 1, mixable: true, spendable: "20000000", most: 3, review: "built 3" });
  });

  it("leaves out a stranger's UTxO whose datum is nested past 128 levels", async () => {
    // What the chain pays for: three boxes from e6's 24 ₳, and not four; the stranger's 3 ₳, which would make 27, never.
    expect(await review((await account("24000000", withDeepDatum)).t, 3)).toBe("built 3");
    expect(await review((await account("24000000", withDeepDatum)).t, 4)).toMatch("doesn't pay for 4 boxes");
    expect(await mixForm("24000000", withDeepDatum)).toEqual({ depth: 1, mixable: true, spendable: "24000000", most: 3, review: "built 3" });
  });
});

// Chunk 51, gap-g3#1 (the trace verifier's test). Lovejoin's quiet rule holds a box's withdraw after the wallet's own
// send (QUIET_AFTER_SEND_MS, lovejoin.ts withdrawDueNow), but nothing holds the wallet's next send after a withdraw:
// the alarm's run puts the sessions' steps first and the withdraw last (runs.ts runEach), and a swap's step waits for
// the unlock alone (sessions.ts act's `go`, `waits`). privacy.md *Timing* says a box "comes back while the wallet is
// unlocked, under rules that keep its way back from lining up with anything else the wallet does" (:440), and "never
// in a run that sent anything else, nor within 5 minutes of the wallet's own send" (:442). The behaviour that promise
// asks for, asserted here: a swap that runs itself, whose funding lands a run after a box's withdraw, doesn't place
// its order within QUIET_AFTER_SEND_MS of that withdraw, and places it once that's over. Fails today: the alarm's next
// run, a minute on, places it.
//
// This is the finder's fix (a). Under fix (b), privacy.md saying it as the code does, this test goes.
//
// The harness is unlock-waits.test.ts's (the quiet after a send, a swap's step at the unlock) and lovejoin-withdraw-
// submit.test.ts's `due`, driven by the real runner (runs.ts runNetworks) as unseen-send-time.test.ts drives it: the
// real WebAssembly, v2's 5 ₳ pool, and fakes of Koios, giveme.my and Minswap.
import { afterEach, describe, expect, it, vi } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { LovejoinService, QUIET_AFTER_SEND_MS, QUIET_PUSH_MS } from "../src/background/lovejoin";
import { Minswap } from "../src/background/minswap";
import { runNetworks, type Runner } from "../src/background/runs";
import { SessionService } from "../src/background/sessions";
import { SESSION_UNLOCKED_AT } from "../src/background/wallet";
import { txIdOf } from "./fixtures/cbor";
import { bytes, swapTx } from "./fixtures/swap-tx";
import { busyFor, loadTestWasm, minswapEstimate, sessionSwap, testBalances, vectors, withdrawPreprod } from "./fakes";
import { ADA, ADA_POOL, ADA_ROWS, adaBox, madeByAdaMix, ownDatum } from "./v2-pools";

const PASSWORD = "correct horse battery";
const HOUR = 3_600_000;
const PHRASE = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!.phrase;
const SWAP = swapTx();
const SWAP_TX = txIdOf(bytes(SWAP));
/** The wallet's box in the 5 ₳ pool. */
const BOX = `${"e1".repeat(32)}#0`;
/** A funding, a withdraw and an order, each built and measured in WebAssembly. */
const SLOW = { timeout: 120_000 };

afterEach(() => void vi.restoreAllMocks());

/**
 * The 12-word phrase's wallet, unlocked an hour ago with its unlock's draws made, one box of its own in v2's 5 ₳ pool
 * (made five hours ago by someone else's mix) due an hour ago, giveme.my's witness and the one-time key's signature
 * stood in for. Returns the services and one alarm run over preprod, as the worker runs it.
 */
async function wallet() {
  const t = testBalances({ pools: [ADA_POOL] });
  // What's written ahead of a submit is stamped by the device's clock, which in the worker is the services' own (sw.ts
  // `now: Date.now`), and runs.ts takes its run's start (`since`) from it: here, the test's clock.
  vi.spyOn(Date, "now").mockImplementation(() => t.clock.now);
  await t.wallet.create(PHRASE, PASSWORD);
  // One spend: the swap's funding takes the 25 ₳ UTxO alone (unlock-waits.test.ts).
  const evaluation = withdrawPreprod.amount.evaluation as { result: unknown[] };
  t.koios.evaluation = { ...evaluation, result: evaluation.result.slice(0, 1) };
  madeByAdaMix(t.koios, "e1".repeat(32));
  t.koios.addedToAccounts.push(...ADA_ROWS, adaBox("e1", await ownDatum(t.wallet), t.clock.now));
  const unlocked = t.clock.now - HOUR;
  await t.wallet.withKeys(() => t.session.set(SESSION_UNLOCKED_AT, unlocked));
  await t.store.set("lovejoin.preprod", { due: [], pools: { [ADA]: { due: [t.clock.now - HOUR] } }, unlock: unlocked });
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  t.minswap.swapCbor = SWAP;
  const signed = (request: string) => {
    const { txCbor } = JSON.parse(request) as { txCbor: string };
    return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
  };
  const collateral = () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch);
  const lovejoin = new LovejoinService({
    ...t.deps,
    wasm: { ...wasm, finishLovejoinWithdraw: signed } as typeof wasm,
    collateral,
    store: t.store,
    pools: async () => [ADA_POOL],
  });
  const sessions = new SessionService({
    ...t.deps,
    wasm: { ...wasm, signScriptSpend: (_key: unknown, request: string) => signed(request) } as typeof wasm,
    collateral,
    store: t.store,
    minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
    alarm: { start: async () => undefined },
  });
  // When Koios took each transaction, by its hash, on the test's clock.
  const at = new Map<string, number>();
  const real = t.koios.fetch;
  t.koios.fetch = async (url, init) => {
    const answer = await real(url, init);
    if (url.endsWith("/submittx")) at.set(txIdOf(t.koios.submitted.at(-1)!), t.clock.now);
    return answer;
  };
  const ctx = { networks: ["preprod"], wallet: t.wallet, sessions, lovejoin, pending: t.pending } as unknown as Runner;
  const alarm = { start: async () => undefined, stop: async () => undefined, starts: () => 0 };
  return { t, sessions, at, run: () => runNetworks(ctx, alarm) };
}

describe("r51 gap-g3#1: the wallet's own send a run after a box's withdraw", SLOW, () => {
  it("waits out the quiet after the withdraw, as the withdraw waits out the quiet after a send", async () => {
    const { t, sessions, at, run } = await wallet();
    // The user starts a swap that runs itself: its funding goes now, from the private balance.
    const funded = t.clock.now;
    const out = await sessions.outBuild("preprod", await sessions.quote("preprod", minswapEstimate.ask));
    await sessions.outSubmit("preprod", out.txHash);
    expect((await t.wallet.sends()).sent).toBe(funded);
    const sent = t.koios.submitted.length;
    const sentSince = () => t.koios.submitted.slice(sent).map((b) => txIdOf(b));

    // The funding is slow to land. Six minutes on, past the quiet after it, the alarm's run finds it not on chain yet:
    // the swap's step sends nothing, and the box due goes, last in the run.
    await busyFor(t, QUIET_AFTER_SEND_MS + 60_000);
    await run();
    // One transaction went in that run, and it's the box's way back: it spends the box.
    expect(sentSince()).toHaveLength(1);
    const withdraw = sentSince()[0]!;
    expect(txInputs(t.koios.submitted.at(-1)!)).toContain(BOX);
    const withdrawn = at.get(withdraw)!;
    expect(withdrawn - funded).toBeGreaterThanOrEqual(QUIET_AFTER_SEND_MS);
    // On chain, its box leaves the pool.
    t.koios.spent.add(BOX);

    // The funding lands, and the account holds what the recorded swap spends (unlock-waits.test.ts `funded`).
    t.koios.confirmations = 1;
    t.koios.addedToAccounts.push({
      ...ADA_ROWS[0]!,
      tx_hash: sessionSwap.utxo.tx_hash,
      tx_index: sessionSwap.utxo.tx_index,
      address: sessionSwap.address,
      value: sessionSwap.utxo.value,
      payment_cred: sessionSwap.keyHash,
      inline_datum: null,
      asset_list: [],
    } as KoiosUtxo);

    // The alarm's next run, a minute on. Nothing of the wallet's goes out within the quiet after the box's way back:
    // not the swap's order either.
    await busyFor(t, 60_000);
    await run();
    const early = sentSince()
      .filter((h) => h !== withdraw)
      .map((h) => ({ tx: h === SWAP_TX ? "the swap's order" : h, msAfterWithdraw: at.get(h)! - withdrawn }));
    expect(early).toEqual([]);

    // Held, never dropped: a run of the alarm's places it once that quiet is over (and any fresh push of it).
    const by = withdrawn + QUIET_AFTER_SEND_MS + QUIET_PUSH_MS[1] + 2 * 60_000;
    while (!sentSince().includes(SWAP_TX) && t.clock.now < by) {
      await busyFor(t, 60_000);
      await run();
    }
    expect(sentSince()).toEqual([withdraw, SWAP_TX]);
    expect(at.get(SWAP_TX)! - withdrawn).toBeGreaterThanOrEqual(QUIET_AFTER_SEND_MS);
  });
});

// Chunk 51's verifier for gap-g3#2: a site's private session whose return's chain through Lovejoin stopped at its
// deposit, which Koios never answered (a 503 on every try) and which never reached a node. Nothing settles that deposit
// for a session that doesn't run itself: act's lost rule (LOST_AFTER_MS) runs only for one with `auto`. So the record
// keeps it as maybe sent for good, chainSoFar reads the chain as started, and every later return comes back directly,
// with no Lovejoin and no word why, though nothing of the chain went in. The right outcome is the one
// return-chain-scope.test.ts pins for a deposit refused outright: brought back again, through Lovejoin. The real
// WebAssembly, Lovejoin v2's 5 ₳ pool (v2-pools.ts), and fakes of Koios, as in that file.
import { describe, expect, it } from "vitest";

import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { Minswap } from "../src/background/minswap";
import { SessionService } from "../src/background/sessions";
import { SPENT_KEEP_MS } from "../src/background/spent";
import { busyFor, sessionSwap, testBalances, vectors } from "./fakes";
import { ADA_POOL, ADA_ROWS } from "./v2-pools";

const PASSWORD = "correct horse battery";
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;

const CHAINS = { timeout: 60_000 };
const AGREES = { jsonrpc: "2.0", method: "evaluateTransaction", result: [] };

function atSession(tx_hash: string, tx_index: number, value: string): KoiosUtxo {
  return {
    tx_hash,
    tx_index,
    address: sessionSwap.address,
    value,
    stake_address: null,
    payment_cred: sessionSwap.keyHash,
    epoch_no: 315,
    block_height: 5_000_000,
    block_time: 1_800_000_000,
    datum_hash: null,
    inline_datum: null,
    reference_script: null,
    is_spent: false,
    asset_list: [],
  } as KoiosUtxo;
}

/** A site's private session 0 holding 40 ₳ and its 5 ₳ collateral, and the 5 ₳ pool its ADA goes into (as return-chain-scope.test.ts). */
async function withSession() {
  const t = testBalances({ pools: [ADA_POOL] });
  await t.wallet.create(account(12).phrase, PASSWORD);
  await t.store.set("sessions.preprod", {
    next: 1,
    sessions: [
      {
        index: 0,
        ownStake: true,
        createdAt: t.clock.now,
        txs: [{ kind: "out", txHash: "ab".repeat(32), at: t.clock.now, confirmed: true }],
        site: { origin: "https://example.org" },
      },
    ],
  });
  t.koios.addedToAccounts.push(atSession("c1".repeat(32), 0, "40000000"), atSession("c2".repeat(32), 1, "5000000"), ...ADA_ROWS);
  t.koios.evaluation = AGREES;
  await t.deps.preferences.set({ lovejoinDepth: 1 });
  const sessions = new SessionService({
    ...t.deps,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
    lovejoin: t.lovejoin,
    sleep: async () => undefined,
  });
  return { t, sessions };
}

type Book = { sessions: Array<{ txs: Array<{ kind: string; unsent?: boolean; inputs?: string[] }> }> };

describe("a site's session whose chain's deposit Koios never answered (r51 gap-g3#2)", () => {
  it("brings it back through Lovejoin again once that deposit is known never to have landed", CHAINS, async () => {
    const { t, sessions } = await withSession();
    const review = await sessions.backBuild("preprod", 0);
    expect(review.lovejoin).toBeDefined();

    // Koios never answers a submit: a 503 every time, so nothing reaches a node (the fake's own submit never runs).
    const fetch = t.koios.fetch;
    let submits = 0;
    t.koios.fetch = async (url, init) => {
      if (url.endsWith("/submittx")) {
        submits++;
        return new Response("upstream unavailable", { status: 503 });
      }
      return fetch(url, init);
    };
    await expect(sessions.backSubmit("preprod", review.txHash)).rejects.toThrow();
    t.koios.fetch = fetch;
    expect(t.koios.submitted).toHaveLength(0);
    const kept = (await t.store.get<Book>("sessions.preprod"))!.sessions[0]!.txs;
    const stopped = (await sessions.list("preprod", true)).find((v) => v.index === 0)!;

    // Well past LOST_AFTER_MS (15 minutes) and SPENT_KEEP_MS (2 hours), the user busy all along, so nothing locks. tx_status
    // still doesn't know the deposit (the fake's confirmations are null), and utxo_info shows what it spends unspent.
    await busyFor(t, SPENT_KEEP_MS + 5 * 60_000);
    await sessions.list("preprod", true);
    const again = await sessions.backBuild("preprod", 0);
    const view = (await sessions.list("preprod")).find((v) => v.index === 0)!;
    console.log(
      JSON.stringify({
        submits,
        recorded: kept.map((x) => ({ kind: x.kind, unsent: !!x.unsent, inputs: x.inputs?.length ?? 0 })),
        afterStop: { chain: stopped.chain, holding: stopped.holding?.lovelace },
        later: { chain: view.chain, holding: view.holding?.lovelace },
        again: { lovejoin: again.lovejoin, lovejoinSkipped: again.lovejoinSkipped, lovelace: again.lovelace, collateralTail: !!again.collateralTail },
      }),
    );

    // Nothing of the chain went in: brought back again, through Lovejoin, as the default says, not directly with no word
    // why (the owner's intent for a deposit refused outright, return-chain-scope.test.ts:146).
    expect(again.lovejoinSkipped).toBeUndefined();
    expect(again.lovejoin).toMatchObject({ depth: 1 });
    // And its page no longer counts a transaction of that chain as sent.
    expect(view.chain?.sent ?? 0).toBe(0);
  });
});
